// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points, acceptedAnswers}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    if (acceptedAnswers && (!acceptedAnswers.includes(answer) || new Set(acceptedAnswers).size !== acceptedAnswers.length ||
        !acceptedAnswers.every(index => Number.isInteger(index) && index >= 0 && index < choices.length))) {
      throw new Error('Invalid accepted answers in ' + year + '/' + grade + '/' + (index + 1));
    }
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, detailSrc, description, pixelWidth, pixelHeight}, i) => ({
      image: src, ...(detailSrc ? {detailSrc} : {}), description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(acceptedAnswers ? {acceptedAnswers} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const tokens = step === 3 ? (lessons[i].acceptedAnswers ?? [letters.indexOf(key)]).map(index => {
        const result = lessons[i].choices[index].replace(/^\[(.*)\][.]?$/, '$1');
        return letters[index] + (result ? ' · ' + result : '');
      }) : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (reviewedKey ? 'reviewed-' + grade + '.pdf' : material.answersFile ?? grade + '-answers.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2006, "10-11", [{"author":"Е. Ренковская","question":"В какой из этих пар слова по смыслу отличаются друг от друга не так, как в остальных?","choices":["<em>пианист — пианистка</em>","<em>журналист — журналистка</em>","<em>машинист — машинистка</em>","<em>радист — радистка</em>","<em>массажист — массажистка</em>."],"key":"В","review":["Машинист и машинистка","Пианистка, журналистка, радистка и массажистка — женщины с той же профессией, которую обозначает соответствующее слово мужского рода.","Машинист управляет машиной, например поездом, а машинистка печатает на пишущей машинке. В этой паре обозначены разные профессии."]},{"author":"О. Шеманаева","question":"Какое из этих слов не может употребляться как название языка?","choices":["<em>цыганский</em>","<em>исландский</em>","<em>майя</em>","<em>грецкий</em>","<em>эсперанто</em>."],"key":"Г","review":["Грецкий и греческий","«Цыганский», «исландский», «майя» и «эсперанто» употребляются как названия языков.","Прилагательное «грецкий» известно по сочетанию «грецкий орех». Язык называется «греческий»."]},{"author":"И. Иткин","question":"<em>— Представляешь! Этот продажный судья назначил в наши ворота три пенальти! — А сколько должен был? — Знаешь, вполне мог ограничиться...</em>","choices":["<em>одним пенальти</em>","<em>одной пенальти</em>","<em>одними пенальти</em>","<em>одним пенальтем</em>","<em>одной пенальтью</em>."],"key":"А","review":["Одним пенальти","«Пенальти» — несклоняемое существительное мужского рода. Оно имеет одну форму в именительном и творительном падежах.","С мужским родом согласуется «одним». Правильно: «одним пенальти»."]},{"author":"Б. Иомдин","question":"Даны три предложения из романа Б. Л. Пастернака «Доктор Живаго»:\n(1) <em>Это было поразительное, ___________, знаменательное свидание!</em>\n(2) <em>С ___________ времен ёлки у Свентицких устраивали по такому образцу.</em>\n(3) <em>Прелесть моя ___________! Пока тебя помнят вгибы локтей моих, пока ещё ты на руках и губах моих, я побуду с тобой</em>.\nКакие прилагательные пропущены в этих предложениях?","choices":["(1) <em>незабвенный</em>, (2) <em>незабываемый</em>, (3) <em>незапамятный</em>","(1) <em>незабываемый</em>, (2) <em>незабвенный</em>, (3) <em>незапамятный</em>","(1) <em>незабвенный</em>, (2) <em>незапамятный</em>, (3) <em>незабываемый</em>","(1) <em>незабываемый</em>, (2) <em>незапамятный</em>, (3) <em>незабвенный</em>","(1) <em>незапамятный</em>, (2) <em>незабываемый</em>, (3) <em>незабвенный.</em>"],"key":"Г","review":["Три слова о памяти","Свидание, которое сильно запомнилось, — «незабываемое». О далёком прошлом обычно говорят «с незапамятных времён».","«Незабвенная» значит «та, о которой всегда помнят». Это определение подходит к обращению «прелесть моя незабвенная»."]},{"author":"И. Рубанов","question":"Когда положение не слишком хорошее, говорят, что оно…","choices":["<em>желает оставлять лучшего</em>","<em>оставляет желать лучшего</em>","<em>не оставляет желать лучшего</em>","<em>оставляет не желать лучшего</em>","<em>не желает оставлять лучшего</em>."],"key":"Б","review":["Оставляет желать лучшего","Когда результат мог бы быть лучше, говорят «оставляет желать лучшего». Это готовый оборот.","В нём «оставляет» — сказуемое, «желать» — инфинитив, а «лучшего» называет недостающее качество."]},{"author":"И. Иткин","question":"<em>На Корсике, на Крите, на Мадагаскаре, на Яве...</em> Тем не менее, говоря о событиях, происходящих на одном из следующих островов, надо употребить предлог <em>в</em>, а не <em>на</em>. На каком?","choices":["Сахалин","Исландия","Кипр","Куба","Мадагаскар."],"key":"Б","review":["На острове, в Исландии","Норма для четырёх названий из списка — «на Сахалине», «на Кипре», «на Кубе», «на Мадагаскаре».","С названием «Исландия» принято «в Исландии». Предлог закрепился в употреблении вместе с этим названием страны."]},{"author":"Е. Муравенко","question":"Выберите цитату, в которой не нарушены современные грамматические нормы.","choices":["<em>И на покорную рояль\nВластительно ложились руки.</em> (А. Блок)","<em>Бывало, он ещё в постеле:\nК нему записочки несут.</em> (А. Пушкин)","<em>Я узна́ю тебя и твой белый вуаль,\nГде роняет цветы благовонный миндаль.</em> (А. Фет)","<em>… И ронял\nВ огонь то туфлю, то журнал.</em> (А. Пушкин)","<em>Но эта важная забава\nДостойна старых обезьян\nХвалёных дедовских времян.</em> (А. Пушкин)"],"key":"Г","review":["Туфля по современной норме","Сейчас пишут «покорный рояль», «в постели», «белую вуаль» и «хвалёных дедовских времён». В соответствующих цитатах употреблены устаревшие формы.","«Туфля» — существительное женского рода, его винительный падеж — «туфлю». В этом месте цитата совпадает с современной нормой."]},{"author":"Е. Муравенко","question":"Если при написании русских слов руководствоваться тем, как пишутся похожие на них английские слова с тем же значением, это иногда приводит к ошибкам. Какое из следующих английских существительных не может вызвать подобную ошибку? (Знания английского языка для решения задачи не требуется.)","choices":["aggressor","opponent","arrest","dessert","metal."],"key":"Б","review":["Удвоенные согласные","Сравните «агрессор», «арест», «десерт» и «металл» с aggressor, arrest, dessert и metal. В каждой паре различается написание одной из согласных.","В opponent и «оппонент» совпадает удвоение п, а остальные согласные одинарные. Написание английского слова не даёт ошибочного образца в этой паре."]},{"author":"Н. Валеева","question":"В каком из этих устойчивых оборотов пропущено не то слово, что в остальных?","choices":["<em>бандит с большой …</em>","<em>скатертью …</em>","<em>по … наименьшего сопротивления</em>","<em>туда и …</em>","<em>на … не валяется</em>."],"key":"В","review":["По пути сопротивления","Четыре оборота восстанавливаются со словом «дорога»: с большой дороги, скатертью дорога, туда и дорога, на дороге не валяется.","Устойчивое выражение — «по пути наименьшего сопротивления». В нём пропущена форма другого слова — «путь»."]},{"author":"Е. Муравенко","question":"В ребусах зашифрованы названия городов, в которых есть победители «Медвежонка». Расшифруйте и расположите по алфавиту эти названия. Какое оказалось в середине списка?","choices":["[ЛИПЕЦК]","[ПЕТРОЗАВОДСК]","[РЯЗАНЬ]","[ПОДОЛЬСК]","[ПЕРМЬ]."],"key":"Б","review":["Алфавит пяти городов","Две ели без начального е, пень без двух последних букв и цирк без ир дают Липецк. В Б «пять» с е вместо я и без мягкого знака, роза, Д внутри О и сук без у дают пет + роза + вод + ск. В В нота ре с я вместо е и Ь за Н дают Рязань.","В Г Л под О и Ь рядом с К, то есть «ь с к», дают Подольск. В Д перо без последней буквы и семь без двух первых дают Пермь. По алфавиту: Липецк, Пермь, Петрозаводск, Подольск, Рязань. Третий — Петрозаводск."],"figure":{"onlyPictures":true,"options":[{"src":"assets/medvezhonok/2006/10-11-10-1.svg","description":"Слева направо: запятая, две ели, пень, две запятые и здание цирка с зачёркнутыми ИР сверху.","pixelWidth":338,"pixelHeight":104},{"src":"assets/medvezhonok/2006/10-11-10-2.svg","description":"Цифра 5 с надписью Я → Е и запятой после неё, роза, буква Д внутри О, сучок с зачёркнутой У сверху.","pixelWidth":358,"pixelHeight":152},{"src":"assets/medvezhonok/2006/10-11-10-3.svg","description":"Нота на нотном стане с надписью Е → Я, затем совмещённые буквы Н и Ь.","pixelWidth":208,"pixelHeight":131},{"src":"assets/medvezhonok/2006/10-11-10-4.svg","description":"Буква Л под О, затем Ь и К как персонажи, держащиеся за руки.","pixelWidth":198,"pixelHeight":107},{"src":"assets/medvezhonok/2006/10-11-10-5.svg","description":"Перо, одна запятая после пера, две запятые перед цифрой 7.","pixelWidth":201,"pixelHeight":87}]}},{"author":"И. Иткин","question":"В современном русском языке слово <em>негде</em> означает ‘нет места (чтобы что-то сделать)’. «Сказка о золотом петушке» А. С. Пушкина начинается так: «<em>Негде, в тридевятом царстве</em>...». А что означает слово <em>негде</em> в этой пушкинской строке?","choices":["‘нигде’","‘где-то’","‘кое-где’","‘там’","то же, что и сейчас."],"key":"Б","review":["Негде в сказке Пушкина","Действие сказки происходит в тридевятом царстве, одном условном месте. Рассказчик вводит это неопределённое место в первой строке.","В пушкинском «негде» сохранилось старое значение «где-то»: «Где-то, в тридевятом царстве…»."]},{"author":"Е. Ренковская","question":"Ниже приведён шуточный диалог из индийской сказки «Хитрый шакал»:\n<em>— Попался тигр в клетку.\n— Странно, сколько я ни встречал тигров, все они были в полоску.</em>\nВ этом диалоге второй собеседник неверно понял фразу первого, потому что воспринял <em>в клетку</em> как:","choices":["часть составного глагольного сказуемого","часть составного именного сказуемого","дополнение","несогласованное определение","обстоятельство."],"key":"Г","review":["Тигр в клетку","Первый собеседник говорит, куда попал тигр. Второй принимает слова «в клетку» за описание рисунка шерсти, по аналогии с «в полоску».","В таком толковании вопрос — «тигр какой?». «В клетку» становится несогласованным определением."]},{"author":"О. Шеманаева","question":"В каком из глаголов пропущена буква <em>и</em>?","choices":["<em>Во сне я лгал и пр…давал,\nИ льстил легко я...\nА я и не подозревал\nВ себе такое.</em> (В. Высоцкий)","<em>Ужели я пр…дам позорному злословью —\nВновь пахнет яблоком мороз —\nПрисягу чудную четвёртому сословью\nИ клятвы крупные до слёз?</em> (О. Мандельштам)","<em>Не будем пр…давать значения злословью.</em> (Б. Окуджава)","<em>Не спи, не спи, художник, не пр…давайся сну!</em> (Б. Пастернак)","<em>«Закладывать» — совсем простое слово,\nА в то же время значит: «пр…давать».</em> (В. Высоцкий)"],"key":"В","review":["Придавать значение","«Придавать значение» значит «считать важным». В этом значении пишется при-: «Не будем придавать значения злословью».","В других примерах употреблены «предавать» в значении измены или выдачи и «предаваться сну» в значении «отдаваться сну». В них нужна е."]},{"author":"Н. Валеева","question":"Даны пять названий российских населённых пунктов: <em>Пермь, Суздаль, Гжель, Тюмень, Ярославль.</em> Сколько среди них имён собственных мужского рода?","choices":["ни одного","одно","два","три","четыре."],"key":"В","review":["Род названий городов","Подберём согласованные определения: древний Суздаль, древний Ярославль. Оба названия мужского рода.","Говорят «древняя Пермь», «знаменитая Гжель», «современная Тюмень». Итого два названия мужского рода."],"reviewedEdition":true,"keyNote":"Печатное условие перечисляет «города», хотя Гжель — село. Вопрос уточнён без изменения списка названий и ключа В."},{"author":"А. Бердичевский","question":"Что такое <em>авторизованный перевод (текста)</em>?","choices":["‘перевод, существенно изменённый переводчиком по сравнению с оригиналом’","‘перевод, одобренный автором оригинала’","‘перевод, выполненный автором оригинала’","‘перевод, разрешённый цензурой’","‘перевод, утверждённый Союзом переводчиков’."],"key":"Б","review":["Кто одобрил перевод","В выражении «авторизованный перевод» существенно согласие автора оригинала. Он видел или разрешил перевод на другой язык.","У такого перевода может быть отдельный переводчик. Определение — «перевод, одобренный автором оригинала»."]},{"author":"И. Рубанов","question":"Поиск в интернете по запросу «Чаплин» указал на страницы, где фигурируют великий комик Чарли Чаплин, его дочь Джеральдина, протоиерей Русской православной церкви Всеволод Чаплин. Как правильно сказать, описывая этот поиск: «<em>Были найдены страницы с ...</em>»?","choices":["<em>Чарли Чаплиным, Джеральдиной Чаплиной, Всеволодом Чаплиным</em>","<em>Чарли Чаплиным, Джеральдиной Чаплин, Всеволодом Чаплиным</em>","<em>Чарли Чаплином, Джеральдиной Чаплиной, Всеволодом Чаплиным</em>","<em>Чарли Чаплином, Джеральдиной Чаплиной, Всеволодом Чаплином</em>","<em>Чарли Чаплином, Джеральдиной Чаплин, Всеволодом Чаплиным</em>."],"key":"Д","review":["Три фамилии Чаплин","Иностранная фамилия «Чаплин» у мужчины склоняется с творительным окончанием -ом, у женщины на согласную остаётся неизменной: «с Чарли Чаплином, Джеральдиной Чаплин».","Русская фамилия на -ин имеет в творительном падеже -ым: «со Всеволодом Чаплиным». Такое сочетание дано в варианте Д."]},{"author":"И. Иткин","question":"Катя и Карина по памяти записали одно четверостишие из стихотворения А. Усачёва. Когда они сравнили то, что у них получилось, выяснилось, что их варианты различаются пунктуацией в третьей строке.\nКатя написала:\n<em>— Эх, — вздыхали червяки, —\nРаньше врали рыбаки!..\nМы послушать их, бывало,\nСами лезли на крючки!</em>\nКарина написала:\n<em>— Эх, — вздыхали червяки, —\nРаньше врали рыбаки!..\nМы, послушать их, бывало,\nСами лезли на крючки!</em>\nКакое из следующих утверждений верно?","choices":["Катя не нарушила правил пунктуации, а Карина нарушила","Карина не нарушила правил пунктуации, а Катя нарушила","правила пунктуации нарушили обе девочки","правила не нарушены в обоих вариантах, варианты синонимичны","правила не нарушены в обоих вариантах, но варианты имеют разный смысл."],"key":"Д","review":["Кто слушает рыбаков","У Кати «послушать их» связано с «лезли» и отвечает на вопрос «зачем?»: червяки лезли на крючок, чтобы послушать рыбаков.","У Карины запятые отмечают вставку со значением «если верить рыбакам»: по словам рыбаков, червяки сами лезли на крючки. Пунктуация допустима в обоих вариантах."]},{"author":"К. Кноп","question":"<em>Полтора раза</em> — это:","choices":["числительное + существительное","два числительных","два существительных","существительное + числительное","наречное выражение."],"key":"А","review":["Полтора раза","«Полтора» обозначает количество и отвечает на вопрос «сколько?». Это числительное.","«Раза» — форма родительного падежа существительного «раз». Получаем числительное и существительное."]},{"author":"А. Бердичевский и Т. Руссита","question":"«<em>На другой день утром я проснулся рано; но Максим Максимыч предупредил меня. Я нашёл его у ворот сидящего на скамейке</em>». (М. Ю. Лермонтов, «Герой нашего времени».) Что означает здесь «<em>предупредил меня</em>»?","choices":["‘накануне сообщил мне, что я проснусь рано’","‘сказал мне, чтобы я спал дальше’","‘проснулся раньше меня’","‘сообщил мне, что я найду его у ворот на скамейке’","‘был очень предупредителен’."],"key":"В","review":["Кто проснулся первым","В отрывке рассказчик проснулся рано, а Максим Максимыч уже сидел у ворот. Более раннее действие обозначено глаголом «предупредил».","В этом старом значении он означает «опередил меня»: Максим Максимыч проснулся раньше рассказчика."]},{"author":"И. Иткин","question":"Какое из следующих событий связано с именем знаменитого русского историка Н. М. Карамзина?","choices":["исключение из русского алфавита буквы <em>Ѣ</em> («ять»)","введение в русский алфавит буквы <em>ё</em>","введение в русский алфавит буквы <em>й</em>","введение гражданского шрифта","разработка теории «трёх штилей языка»."],"key":"Б","review":["Карамзин и буква ё","Имя Карамзина традиционно связывают с употреблением и распространением буквы ё в печати. Вариант Б называет именно эту букву.","Предложение использовать ё прозвучало раньше, на заседании Российской академии с участием Екатерины Дашковой. Карамзин помог закрепить её в печатном употреблении."]},{"author":"К. Кноп и А. Пасечник","question":"Даны три финских сложных слова:\njääkarhu (йаакарху) — <em>белый медведь</em>;\npesujauhe (песуйаухе) — <em>стиральный порошок</em>;\njauhekahvi (йаухекахви) — <em>молотый (или растворимый) кофе</em>.\nЧто означает финское сложное слово pesukarhu (песукарху)?","choices":["<em>бурый уголь</em>","<em>ластик</em>","<em>бурый медведь</em>","<em>сахар-песок</em>","<em>енот-полоскун</em>."],"key":"Д","review":["Финский «стирающий медведь»","«Karhu» — медведь, как в «jääkarhu». «Pesu» относится к стирке или мытью, как в названии стирального порошка «pesujauhe».","«Pesukarhu» буквально означает «моющий медведь». Эта подсказка ведёт к еноту-полоскуну, известному движениями лап, похожими на полоскание."]},{"author":"А. Бердичевский и И. Рубанов","question":"Перед вами — цитата из романа П. Мельникова-Печёрского «На горах»: «Смутившийся игумен возвёл очи горе». Что означает «<em>возвёл очи горе</em>»?","choices":["‘посмотрел на гору’","‘горестно поднял глаза’","‘поднял глаза вверх’","‘подвёл глаза чёрным в знак траура’","‘закрыл глаза’."],"key":"В","review":["Взгляд вверх","«Очи» — глаза, а «возвёл» означает «поднял». Церковнославянское наречие «горе́» связано с направлением вверх.","Игумен поднял глаза вверх. Наречие «горе́» отличается от существительного «го́ре» значением и ударением."]},{"author":"И. Иткин","question":"В некоторых русских словах, начинающихся на «<em>об</em> + гласная», после <em>об-</em> раньше был звук <em>в</em>, впоследствии исчезнувший: <em>об-вернуть</em> → <em>обернуть</em> (ср. <em>повернуть</em>), <em>об-волочка</em> → <em>оболочка</em> (ср. <em>обволакивать</em>) и т. д. В каком из этих слов звука <em>в</em> после <em>об-</em> никогда не было?","choices":["<em>обет</em>","<em>обед</em>","<em>обонять</em>","<em>обоз</em>","<em>обычай</em>."],"key":"Б","review":["Исчезнувший звук в","«Обет» связан с «ответом» и «заветом», «обонять» — с «вонью», «обоз» — с «возом», «обычай» — с «привычкой». В этих корнях раньше был в и после об-.","«Обед» связан со словами «еда» и «есть». Корень, который шёл после об-, начинался с гласного."]},{"author":"И. Рубанов","question":"<em>После нулевой ... со Словакией сборная России не попала в финал Чемпионата мира по футболу</em>. Какое слово мы заменили многоточием?","choices":["<em>ничей</em>","<em>ничьи</em>","<em>ничьей</em>","<em>ничьёй</em>","<em>нечьей</em>."],"key":"В","review":["После нулевой ничьей","Предлог «после» требует родительного падежа: после чего? — после ничьей. Прилагательное тоже стоит в родительном: «нулевой».","«Ничьёй» с ё — форма творительного падежа: «матч закончился ничьёй». Здесь пишем «после нулевой ничьей»."]},{"author":"И. Иткин","question":"Даны глаголы <em>насадить, осадить, просветить</em>. Какие из них образуют несовершенный вид двумя разными способами?","choices":["только <em>насадить</em>","только <em>осадить</em>","только <em>просветить</em>","<em>насадить</em> и <em>осадить</em>","все."],"key":"Д","review":["Формы несовершенного вида","От «насадить» можно образовать «насаживать» и «насаждать», от «осадить» — «осаживать» и «осаждать».","От «просветить» получаются «просвечивать» в буквальном значении и «просвещать» в значении обучения. У каждого глагола есть две формы."]},{"author":"И. Рубанов","question":"В скольких различных смыслах можно понять фразу:\n<em>Будущее детей Владимира радует?</em>","choices":["в одном","в двух","в трёх","в четырёх","по крайней мере в пяти."],"key":"Д","review":["Кого радует будущее","У глагола «радует» можно менять границу между подлежащим и дополнением. Будущее детей Владимира радует кого-то. Будущее детей радует самого Владимира. Будущее радует детей Владимира.","Слово «Владимира» может обозначать и человека, и город. Тогда «будущее детей Владимира радует кого-то» можно понимать как речь о детях из города Владимира, а «будущее радует детей Владимира» — об этих детях. Получается по меньшей мере пять смыслов."]},{"author":"С. Переверзева","question":"В каком институте Академии наук был создан синтетический кристалл фианит?","choices":["в химическом","в физическом","в геологическом","в минералогическом","в институте кристаллографии."],"key":"Б","review":["Фианит и ФИАН","Название «фианит» начинается с аббревиатуры ФИАН. АН обозначает Академию наук.","ФИ — Физический институт. Кристалл назван по институту, в котором его создали."]},{"author":"Е. Муравенко","question":"Раскройте скобки в данных словах и словосочетаниях, выбрав слитное, раздельное или дефисное написание. В четырёх случаях это можно сделать по-разному в зависимости от смысла, и лишь в одном случае возможен единственный вариант написания, несмотря на разные смыслы. Что это за случай?","choices":["(<em>пол</em>)<em>овцы</em>","(<em>пол</em>)<em>лошади</em>","(<em>пол</em>)<em>комнаты</em>","(<em>пол</em>)<em>летнего домика</em>","(<em>пол</em>)<em>литровой банки</em>."],"key":"Г","review":["Пол летнего домика","«Пол летнего домика» может означать его настил. Здесь «пол» — обычное существительное, которое пишется отдельно.","Если имеется в виду половина домика, слово «летнего» отделяет «пол» от слова «домика», поэтому написание также раздельное. В других вариантах разница видна: «пол-овцы / пол овцы», «пол-лошади / пол лошади», «полкомнаты / пол комнаты», «пол литровой банки / пол-литровой банки»."]},{"author":"И. Иткин","question":"У какого из этих существительных есть однокоренное слово, в котором выделяется редкая приставка <em>ко-</em>?","choices":["<em>лодка</em>","<em>пытка</em>","<em>ров</em>","<em>рытвина</em>","<em>улица</em>."],"key":"Д","review":["Коулок и улица","Слово «улица» родственно словам «переулок» и «закоулок». В них исторически выделяется корень -ул-.","В «закоулке» сохранилась редкая приставка ко- перед -ул-, а перед ней стоит за-. Остальные слова такого родственника не дают."]},{"author":"С. Бурлак","question":"Винни-Пух, Бэмби и Знайка шли по Волшебной стране и вдруг увидели табличку с непонятными рисунками и надписью «БУКИ».\n— Странно! — воскликнули они хором.\n— Много я видел разных бук — они совсем не такие! — сказал Винни-Пух.\n— Много я видел разных буков — они совсем не такие! — сказал Бэмби.\n— Много я видел разных буки — они совсем не такие! — сказал Знайка.\nКто из них точно сделал грамматическую ошибку?","choices":["только Винни-Пух","только Бэмби","только Знайка","Бэмби и Знайка","никто."],"key":"Д","review":["Три разных «Буки»","«Буки» может быть множественным числом от «бука», то есть нелюдимый человек, или от «бук», то есть дерево. В родительном множественного получаются «бук» и «буков».","«Буки» также старое неизменяемое название буквы Б. Винни-Пух, Бэмби и Знайка могли иметь в виду разные слова, и все три формы грамматически возможны."]}], {"year":2006,"grade":"10-11","tasksFile":"10-11.pdf","answersFile":"10-11-answers.pdf","sourceUrl":"https://konkurs43.ru/rm/task2006.zip"}), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
